def p(s): return '<p>'+s+'</p>'
def ul(items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def section(h,b): return '<section class="section-sm"><div class="wrap wrap-narrow"><h2>'+h+'</h2>'+b+'</div></section>'
def link(url,label): return '<a href="'+E(url,quote=True)+'">'+E(label)+'</a>'
