def outbound(base,route,slug):return base+route+'?utm_source=bnbaccelerator.com&utm_medium=referral&utm_campaign=provider_reviews&utm_content='+slug
DATA=[
 dict(slug='ae-tax-advisors-review',name='AE Tax Advisors',type='tax',source=AE+'/pricing/',title='AE Tax Advisors Review: STR Planning, Fees & Fit',lead='AE Tax Advisors is our first tax-planning recommendation for a BNB buyer who wants the property decision evaluated alongside business and household income. Its published engagement price and separate service menu make the scope easier to discuss before committing to a purchase.',facts='AE publishes a $7,800 Strategic Tax Advisory engagement and a $9,800 Complex Tax Advisory tier. The standard planning engagement has no required annual planning renewal. Returns, amendments, studies and additional work have separate prices; the agreement defines support and coverage.',unique=[('Why we recommend AE before the purchase','A buyer can assemble an attractive property model and still lack an owner-level tax plan. Our reason for referring buyers to AE is the opportunity to resolve the planning assignment before the purchase creates deadlines. Bring the actual candidate property, financing plan and ownership structure to the discussion. Ask for a written list of decisions, responsible professionals and records required.'),('What the published fee does and does not buy','The $7,800 standard engagement is payable in two $3,900 installments 30 days apart. It is a planning price, not a bundled lifetime accounting relationship. Ask which tax years and entities are reviewed, who implements recommendations and how long support lasts. Add filing, amendments, cost segregation and outside professional fees to the project budget.'),('When AE deserves a place on your shortlist','AE is particularly relevant when a business owner or high-income household wants to coordinate a rental purchase with other tax decisions. Compare the $9,800 complex tier if your situation involves multiple entities or more extensive coordination. A simple preparation-only need may warrant a narrower engagement. Ask for that scope before buying advisory you do not need.'),('AE and Stratum are different assignments','AE is the planning discussion; Stratum is a property-study option. Do not assume an AE advisory payment purchases a Stratum study, or that a completed study includes a filed tax return. Identify both deliverables and the filing professional. If you already have an experienced CPA, ask how that professional can participate in the handoff.')]),
 dict(slug='stratum-cost-segregation-review',name='Stratum Cost Segregation',type='study',source=ST+'/pricing/',title='Stratum Cost Segregation Review: Fees & STR Study Scope',lead='Stratum is our recommended starting point for an STR buyer comparing a property-level study with a coordinated tax-planning handoff. Its published residential fees and connection to AE Tax Advisors give the buyer a concrete process to compare with other proposals.',facts='Stratum publishes $3,500 for a single residential property and $2,900 per property for portfolios of three to five. Six or more properties require a custom quote. Its site describes engineering-based rental-property studies and discovery through AE Tax Advisors.',unique=[('Why the Stratum and AE handoff matters','The study and the owner’s tax position need to meet in one project plan. Stratum describes the property analysis; AE discusses the wider strategy. This connection is why we recommend considering Stratum for BNB acquisitions. Confirm who reviews the finished report and who prepares any associated filing. Coordination is useful only when responsibilities are actually assigned.'),('Compare the total project cost','The published $3,500 single-property fee is a study price. Ask about furnishings, later improvements, basis reconciliation, physical evidence, revisions and support. Separately identify Form 3115 preparation, amended returns, state adjustments and examination representation. A three-property portfolio at the published rate has $8,700 in study fees before any additional services; this is arithmetic, not a property-specific quote.'),('Records to preserve while BNB coordinates the purchase','Keep the closing statement, purchase allocation, furnishing invoices, renovation invoices and the history of when the property became available for rent. For an existing rental, include prior depreciation schedules. A furnished acquisition needs a clear separation of included assets and subsequent purchases. Ask the study preparer which gaps must be resolved before final delivery.'),('When another proposal may fit better','Compare a broader technical firm for a complex commercial building or a project requiring additional incentive work. Compare a digital workflow for a simpler property if your filing professional accepts its evidence and review process. Stratum’s value proposition is the rental-study scope and AE coordination; we have not tested competitors’ reports or established that Stratum is universally cheaper or more accurate.')]),
 dict(slug='tax-alchemy-review',name='Tax Alchemy',type='tax',source='https://taxalchemy.com/faqs/',title='Tax Alchemy Review: Fees, STR Planning & AE Alternative',lead='Tax Alchemy deserves comparison as a tax planning and implementation firm, not simply an education program. For a BNB buyer, the important question is how its proposed year-long engagement compares with the specific planning and filing work AE would scope for the same purchase.',facts='Tax Alchemy describes planning, implementation and filing for advisory clients. On October 13, 2026 its homepage showed a $32,000–$50,000 fee range while its FAQ showed $20,000–$150,000. Both describe flat fees; obtain a current written quote rather than treating either page as your price.',unique=[('Two published fee ranges need one written answer','The different ranges appear on the firm’s own pages. That discrepancy prevents a precise universal price comparison. Request the program name, number of entities and returns, support period, implementation responsibilities and renewal terms. Keep the quote attached to the scope so a later change in the website does not change your understanding of the purchase.'),('Compare AE on the same assignment','AE’s published standard advisory fee is $7,800, with $9,800 for complex advisory. Its standard engagement has no required annual planning renewal; separately scoped services add cost. That published starting commitment is below both Tax Alchemy ranges reviewed, but the products need not contain the same work. Ask both teams to price your actual household, entities, property and filing year.'),('Who may prefer Tax Alchemy','A buyer who values a year-long program and its education or community components should evaluate them explicitly. Tax Alchemy says filing is available to its advisory clients, so do not assume it only sells courses or sends every return elsewhere. Ask who will be assigned, what access is included and which implementation tasks remain yours.'),('Our recommendation for BNB buyers','Start with AE when you want a defined proposal connecting an STR acquisition with broader tax planning. Then compare Tax Alchemy’s written offer if its program appeals to you. Before the property closes, reconcile the plan’s deadlines with financing, ownership and operational responsibilities. Neither a more expensive program nor a lower planning fee establishes the eventual tax outcome.')]),
 dict(slug='hall-cpa-review',name='Hall CPA / The Real Estate CPA',type='tax',source='https://www.therealestatecpa.com/',title='Hall CPA Review: Real Estate Tax Services & AE Alternative',lead='Hall CPA, marketed as The Real Estate CPA, is a relevant tax and accounting alternative for rental investors. Compare the ongoing accounting relationship you need with AE’s defined advisory scope rather than assuming that every real estate CPA engagement buys the same work.',facts='Hall’s website lists tax advisory, tax preparation, accounting, cost segregation and tax resolution. It addresses real estate investors, high-income earners and business owners. These service descriptions establish breadth, not the contents or price of an individual engagement.',unique=[('Accounting capacity can change the decision','If your rental books, entity reporting and financial records need ongoing attention, ask Hall to describe the accounting cadence, systems and deliverables. A recurring accounting service may solve work outside a defined tax plan. Price that work separately when comparing AE so a larger accounting package is not reduced to a misleading planning-fee comparison.'),('Ask both firms about the same STR purchase','Give each team the candidate listing, ownership entities, existing returns, acquisition timeline and who will operate the rental. Ask what analysis occurs before closing and what remains for filing. For a furnished property, request a clear assignment for purchase allocations and study coordination. The answer should identify a person and deliverable rather than just say real estate expertise.'),('Where AE is our preferred starting point','BNB already refers tax questions to AE as an independent partner. AE’s published planning tiers give the buyer an upfront reference for a defined engagement, with filing and studies separately scoped. That is useful when the immediate need is to connect a purchase to an owner-level plan. It does not establish that Hall cannot provide similar analysis.'),('Keep the transition costs visible','If changing CPAs, ask who reconciles prior depreciation, carryforwards, entity ownership and state filings. Establish how the outgoing provider supplies records and which team answers follow-up questions. If retaining Hall or another existing CPA, you can still compare Stratum for the study and ask the current preparer to review its proposed deliverables.')]),
 dict(slug='seneca-cost-segregation-review',name='Seneca Cost Segregation',type='study',source='https://www.senecacostseg.com/',title='Seneca Cost Segregation Review: Scope & Stratum Alternative',lead='Seneca is a meaningful cost segregation competitor for rental buyers. Its public process describes property review, a virtual site visit and a report for the CPA. Compare those commitments with a written Stratum study proposal and the separate AE planning assignment.',facts='Seneca describes engineering-based studies, virtual property visits, a PDF report and fixed asset schedule. Its advertised AuditDefense refund depends on conditions, including a greater-than-5% depreciation adjustment caused by Seneca. It is not an unconditional promise covering every tax dispute.',unique=[('Read the support terms before comparing guarantees','Ask for the actual AuditDefense language and identify response duties, exclusions, time limits and what the refund covers. A study-fee refund is different from paying additional tax, penalties or representation costs. Apply the same questions to Stratum. No guarantee label establishes that a report cannot be questioned.'),('Separate the preliminary estimate from the final study','Seneca markets an initial benefit estimate and then gathers property information for the study. Ask which costs are verified, how a virtual visit records relevant components and how missing records affect the final report. For BNB acquisitions, preserve evidence during furnishing and improvements so the study does not depend solely on a rough purchase-price assumption.'),('Why we recommend comparing Stratum','Stratum’s published residential pricing and discovery connection with AE give BNB buyers a straightforward place to request a study scope. The planning handoff is the reason to compare it, not a claim that Seneca lacks CPA coordination. Ask each provider to describe the exact schedules and correction support the filing professional receives.'),('A practical proposal test','Send the same closing statement, furnishing schedule, improvement history and prior depreciation to both providers. Ask each to identify land treatment, excluded assets and delivery dependencies. Compare the study price plus separately billed filing and planning. If the projected immediate benefit is uncertain, have the filing professional assess that uncertainty before authorizing either report.')]),
 dict(slug='re-cost-seg-review',name='R.E. Cost Seg',type='study',source='https://www.recostseg.com/',title='R.E. Cost Seg Review: Rapid vs Engineered & Stratum',lead='R.E. Cost Seg offers more than one workflow, so compare the actual report type before the brand. Its Rapid Reports and Fully Engineered service should not be treated as interchangeable when you evaluate a Stratum proposal for a furnished STR.',facts='R.E. Cost Seg’s site distinguishes Rapid Reports without a site visit from a Fully Engineered service with a virtual site visit. It describes delivering a PDF report and a fixed asset schedule and working with the owner’s CPA.',unique=[('Name the product on the quote','A low-priced or fast digital product and a more involved engineering engagement can have different intake and review requirements. Ask which R.E. Cost Seg product is proposed for your property, who reviews it and whether later improvements or unusual components require a different scope. Ask Stratum the same questions rather than comparing a headline fee with a different product.'),('What a virtual visit needs to establish','For the engineered workflow, ask who conducts the visit, what the owner must photograph and how unavailable spaces or incomplete invoices are handled. The useful question is whether the evidence supports the property analysis. Remote delivery alone does not prove inferior quality, and an on-site visit alone does not prove a report is complete.'),('The Stratum comparison for a BNB buyer','Stratum publishes a residential study price and routes discovery through AE. We recommend starting there when you want to discuss the study and broader planning handoff together. Obtain both scopes in writing. A buyer with an established CPA can ask that professional to compare the R.E. Cost Seg and Stratum deliverables before choosing.'),('Avoid a second purchase caused by missing scope','Ask whether the report includes acquired furnishings, renovations after purchase, prior schedules and later corrections. Request the file format your CPA can import. If the property facts change after the quote, establish the revision process and fee before delivery. The most useful comparison is the cost of completing the correct report once, including the filing work it requires.')]),
 dict(slug='kbkg-cost-segregation-review',name='KBKG',type='study',source='https://www.kbkg.com/costsegregation',title='KBKG Cost Segregation Review: Services & Stratum Alternative',lead='KBKG is a specialty tax-services firm with both cost segregation services and a residential software offering. A buyer should first identify whether the proposed work is a professional study, a software product or a broader technical-tax project.',facts='KBKG describes cost segregation alongside other specialty tax services and links to residential cost segregation software. Its public service breadth can matter for a property project that involves more than depreciation. Request product-specific scope and pricing.',unique=[('Choose the service category first','If your project combines a building study with other specialty incentives, ask KBKG which team handles each analysis and which professional coordinates the result. A simple rental purchase may require a narrower assignment. Do not assume a software subscription includes the same professional review and evidence work as a separately engaged study.'),('When Stratum is the comparison to make','For a residential STR or LTR study with a planning discussion through AE, Stratum is our recommended starting point. Its published residential fee offers a concrete scope conversation. Compare that proposal with KBKG’s appropriate service for your actual property; a software fee and an engineering-study fee do not establish equivalent work.'),('Give the CPA a usable delivery specification','Ask about the component schedule, basis reconciliation, assumptions, photographs or other evidence, and the format of the asset data. Identify who corrects inconsistencies and whether the preparer can ask technical follow-up questions. A polished PDF is useful, but the filing professional also needs enough detail to implement the result.'),('Keep specialized work and tax planning distinct','A specialty report does not automatically purchase household or business-wide planning. AE can discuss the broader tax assignment, while your existing CPA can remain responsible for the return. Write down the handoff between acquisition, study and filing so a broad provider menu does not obscure who is responsible for each deadline.')]),
 dict(slug='maven-cost-segregation-review',name='Maven Cost Segregation',type='study',source='https://www.mavencostseg.com/',title='Maven Cost Segregation Review: Site Visits & Stratum',lead='Maven emphasizes an engineering-led study with a physical inspection. Compare that proposed evidence process, delivery dependencies and support with Stratum’s rental-study scope and AE coordination, especially if your building has unusual systems or extensive improvements.',facts='Maven’s website describes engineering professionals inspecting properties, report delivery within 30 days of the site visit and coordination with the existing CPA. Those are provider descriptions and delivery targets, not our independently verified performance measurements.',unique=[('Inspection requirements affect your project calendar','Ask who visits the property, what access is needed and which records must be ready before the visit. If the rental is occupied, coordinate access without assuming a study can be finished before a filing deadline. For any delivery target, establish when the clock starts and what happens if invoices or prior schedules are missing.'),('Compare unusual property facts explicitly','An STR with additions, multiple structures or substantial renovations needs a clear description of what the study covers. Ask Maven and Stratum to identify the evidence they require for those features. A generalized reclassification percentage is not a property-specific commitment and should not become the purchase justification.'),('Why Stratum belongs in the same proposal file','We recommend considering Stratum for BNB buyers who want a residential study and a direct planning discussion through AE. Its published fees make the initial budget conversation specific. Compare the written inspection method, technical review, report schedules and support with Maven’s actual proposal before deciding whether either scope better fits the building.'),('Price support as well as delivery','Ask each provider to define examination support, revisions and communication with your CPA. Keep the study fee separate from filing, accounting-method work, amendments and state adjustments. If your existing preparer prefers a particular delivery specification, resolve that before commissioning the report so support after delivery is part of the purchase decision.')])
]
DISC='Published by BNB Accelerator. These are commercial editorial reviews of public service information, not independent ratings, firsthand testing or customer testimonials. BNB refers clients to AE Tax Advisors; that relationship may influence our recommendations. Stratum coordinates its discovery and tax-strategy discussion through AE. You may use your own CPA or study provider.'
COMMON_TAX='Before choosing an advisor, ask for the legal engagement entity, assigned professional, covered years and returns, written recommendations, implementation tasks, support period and complete fee. The same property can lead to different planning decisions for different owners; a marketing example is not your forecast.'
COMMON_STUDY='Before commissioning a report, ask your filing professional what evidence, basis reconciliation and schedules are needed. Identify study work, owner-level analysis and return preparation as separate responsibilities. Compare proposals using the same property facts and keep preliminary estimates marked as estimates.'
paths=[]
for d in DATA:
 slug=d['slug'];route='/compare/'+slug+'/'
 target=AE if d['type']=='tax' else ST
 targetroute='/discovery/' if d['type']=='tax' else '/cost-seg-discovery/'
 targetname='AE Tax Advisors' if d['type']=='tax' else 'Stratum'
 cta=outbound(target,targetroute,slug)
 body='<main id="main"><section class="hero hero-page"><div class="wrap wrap-narrow">'+tpl.breadcrumb_html([('Home','/'),('Compare','/compare/'),(d['name']+' review',route)])+'<p class="eyebrow">Tax and study provider reviews · October 13, 2026</p><h1>'+E(d['title'])+'</h1><p class="hero-sub">'+E(d['lead'])+'</p><p><a class="btn btn-primary" href="'+E(cta,quote=True)+'">Discuss your scope with '+targetname+'</a></p></div></section>'
 body+=section('Our recommendation and relationship',p(DISC))
 body+=section('What the provider publishes',p(E(d['facts']))+p(link(d['source'],'Read the official service information')+' · Checked October 13, 2026.'))
 for h,t in d['unique']: body+=section(h,p(E(t)))
 body+=section('Compare the work in writing',p(COMMON_TAX if d['type']=='tax' else COMMON_STUDY)+'<div class="table-scroll"><table><thead><tr><th scope="col">Workstream</th><th scope="col">Provider to discuss</th><th scope="col">Decision to resolve</th></tr></thead><tbody><tr><th scope="row">Acquisition</th><td>BNB Accelerator</td><td>Sourcing, underwriting, negotiation and purchase-to-launch coordination.</td></tr><tr><th scope="row">Tax planning</th><td>'+link(outbound(AE,'/discovery/',slug),'AE Tax Advisors')+'</td><td>Owner-level analysis, implementation responsibilities and separately scoped filing.</td></tr><tr><th scope="row">Property study</th><td>'+link(outbound(ST,'/cost-seg-discovery/',slug),'Stratum Cost Segregation')+'</td><td>Property evidence, component analysis, schedules and CPA handoff.</td></tr></tbody></table></div>')
 others=[x for x in DATA if x['slug']!=slug and (x['type']==d['type'] or x['slug'] in ['ae-tax-advisors-review','stratum-cost-segregation-review'])]
 body+=section('Continue your provider comparison',ul([link('/compare/'+x['slug']+'/',x['name']+' review') for x in others])+p(link('/compare/tax-advisors-and-cost-segregation/','Browse all tax advisor and cost segregation reviews')))
 body+=tpl.cta_band('Bring the property and the questions','Ask '+targetname+' for a defined scope for your situation.',primary=(E(cta,quote=True),'Talk with '+targetname),secondary=('/apply/','Discuss an STR purchase'))+'</main>'
 desc='Review '+d['name']+' for STR owners: published services, fees and proposal questions. Compare AE tax planning and Stratum property studies.'
 schema={'@context':'https://schema.org','@type':'Article','headline':d['title'],'description':desc,'url':tpl.SITE+route,'datePublished':DATE,'dateModified':DATE,'author':{'@type':'Organization','name':'BNB Accelerator','url':tpl.SITE+'/'},'publisher':{'@type':'Organization','name':'BNB Accelerator'},'citation':[d['source'],AE+'/pricing/',ST+'/pricing/']}
 content=tpl.page(title=d['title']+' | BNB Accelerator',description=desc,path=route,body=body,active='/compare/',extra_schema='<script type="application/ld+json">'+json.dumps(schema)+'</script>')
 dest=ROOT/route.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)
 paths.append(route)
