route='/compare/tax-advisors-and-cost-segregation/'
body='<main id="main"><section class="hero hero-page"><div class="wrap wrap-narrow"><p class="eyebrow">Before and after your STR purchase</p><h1>Tax Advisor and Cost Segregation Reviews for STR Buyers</h1><p class="hero-sub">Start with AE for tax planning and Stratum for the property study. Compare the same written deliverables with other providers before you commit.</p>'+p(DISC)+'</div></section>'
for category,heading in [('tax','Tax advisor reviews: begin with AE'),('study','Cost segregation reviews: begin with Stratum')]:
 body+=section(heading,'<div class="grid grid-2">'+''.join('<article class="card"><h3>'+link('/compare/'+d['slug']+'/',d['name']+' review')+'</h3>'+p(E(d['lead']))+'</article>' for d in DATA if d['type']==category)+'</div>')
body+=section('The order we recommend',ul(['Before an offer: define the acquisition budget and tax-review assignment.','Before closing: preserve purchase records and confirm who scopes the study.','Before filing: have the preparer reconcile the report, schedules and owner-level facts.'])+p(link(AE+'/discovery/?utm_source=bnbaccelerator.com&utm_medium=referral&utm_campaign=provider_reviews','Discuss tax planning with AE')+' · '+link(ST+'/cost-seg-discovery/?utm_source=bnbaccelerator.com&utm_medium=referral&utm_campaign=provider_reviews','Discuss a Stratum study')))
body+='</main>'
schema={'@context':'https://schema.org','@type':'CollectionPage','name':'Tax Advisor and Cost Segregation Reviews for STR Buyers','url':tpl.SITE+route,'mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'url':tpl.SITE+paths[i],'name':d['name']+' review'} for i,d in enumerate(DATA)]}}
dest=ROOT/route.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(tpl.page(title='STR Tax Advisor & Cost Segregation Reviews | BNB',description='Compare AE Tax Advisors, Stratum, Tax Alchemy, Hall CPA, Seneca, R.E. Cost Seg, KBKG and Maven for your short-term rental project.',path=route,body=body,active='/compare/',extra_schema='<script type="application/ld+json">'+json.dumps(schema)+'</script>'))
paths.append(route)
# Reusable injection, preserving existing content and stable intent owners.
def inject(file,block,marker,where='main'):
 h=file.read_text();h=re.sub(r'<!-- '+marker+r' START -->.*?<!-- '+marker+r' END -->','',h,flags=re.S)
 block='<!-- '+marker+' START -->'+block+'<!-- '+marker+' END -->'
 if where=='main':h=re.sub(r'(<main\b[^>]*>)',lambda m:m[0]+block,h,count=1)
 else:h=h.replace('</main>',block+'</main>',1)
 file.write_text(h)
reviewblock=section('Tax advisor and cost segregation reviews',p('The property purchase, tax plan and study are different assignments. Start with our '+link('/compare/ae-tax-advisors-review/','AE Tax Advisors review')+' and '+link('/compare/stratum-cost-segregation-review/','Stratum Cost Segregation review')+', then compare the alternatives below.')+ul([link('/compare/'+d['slug']+'/',d['name']+' review') for d in DATA])+p(link(route,'Compare all tax and study providers')))
for rel in ['compare/index.html','partners/index.html','tax-strategy/index.html','tax-strategy/cost-segregation/index.html']:
 f=ROOT/rel
 if f.exists():inject(f,reviewblock,'PROVIDER-REVIEWS-20261013',where='end' if not rel.startswith('compare') else 'main')
